INSERT INTO experiment_scenario (scenario_code, scenario_name, description, enabled)
VALUES
    ('stable', '正常协同', '全链路稳定运行的基线演示场景', TRUE),
    ('degraded', '通信退化', '存在时延抬升与随机丢包的退化场景', TRUE),
    ('lost', '失联自治', '部分场站失联并进入本地自治的场景', TRUE),
    ('recovering', '恢复同步', '链路恢复后逐步重建协同的场景', TRUE),
    ('T0_STABLE_BASELINE', '稳定基线', '无故障注入，记录正常协同状态下的基线数据。', TRUE),
    ('T1_LATENCY_JITTER', '通信时延抖动', '对目标场站注入稳定可重复的时延抬升和抖动。', TRUE),
    ('T2_RANDOM_PACKET_LOSS', '随机丢包', '按固定节奏丢弃目标场站部分遥测消息。', TRUE),
    ('T3_BURST_PACKET_LOSS', '突发丢包', '周期性连续丢弃目标场站遥测，形成短时突发丢包。', TRUE),
    ('T4_INTERMITTENT_DISCONNECT', '间歇中断', '目标场站在线状态按固定周期切换，模拟弱覆盖边缘中断。', TRUE),
    ('T5_FULL_LOSS_AUTONOMY', '完全失联自治', '目标场站停止心跳和遥测，触发后端心跳超时与本地自治判断。', TRUE),
    ('T6_BANDWIDTH_LIMIT', '带宽受限', '目标场站保持心跳，但遥测上报频率降低。', TRUE),
    ('T7_OUT_OF_ORDER_DUPLICATE', '乱序与重复消息', '目标场站周期性发送重复序号或旧时间戳遥测，验证后端幂等和过期拒绝。', TRUE),
    ('T8_STALE_TELEMETRY', '遥测陈旧冻结', '目标场站保持功率冻结并持续发送陈旧采样时间。', TRUE),
    ('T9_RECOVERY_SYNC', '恢复同步', '目标场站从失联状态逐步恢复，先进入恢复同步再回到正常协同。', TRUE),
    ('T10_CONTROL_ACK_LOSS', '控制确认丢失', '预留控制回执丢失实验，当前模拟器仅记录命令并保持遥测退化。', TRUE)
ON CONFLICT (scenario_code) DO NOTHING;

